            (0x80000000, 1, True, 0x7fffffff, (False, False, True, True)),
            (0x7fffffff, 0xffffffff, True, 0x80000000, (True, False, False, True)),
            (0xffffffff, 0xffffffff, True, 0, (False, True, True, False)),
